WITH kept_keys AS (SELECT firmware, device_code FROM device_readings EXCEPT DISTINCT SELECT firmware, device_code FROM device_readings WHERE temp_c >= 23), reconciled AS (SELECT s.* FROM device_readings s INNER JOIN kept_keys k ON s.firmware = k.firmware AND s.device_code = k.device_code) SELECT CASE WHEN pressure >= 1032 THEN 'PREMIUM' ELSE 'STANDARD' END AS pressure_tier, device_code, DATE_TRUNC('DAY', reading_ts) AS activity_day, BIT_AND(status_bits) AS status_bits_bit_and, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, GROUPING(CASE WHEN pressure >= 1032 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM reconciled GROUP BY CUBE (CASE WHEN pressure >= 1032 THEN 'PREMIUM' ELSE 'STANDARD' END, device_code, DATE_TRUNC('DAY', reading_ts))
